(6761887, 1012347, 96574, '<td valign="top">should have been much higher. the colors are mesmerizing.</td>', 'should have been much higher. the colors are mesmerizing.', '2012-05-07 09:29:14.000000', NULL, 0),
(6761891, 1011465, 12611, '<td valign="top">You executed a very difficult shot, in the parameters of the challenge, in that it is what might be expected, yet much better than expected. for that, congrats!</td>', 'You executed a very difficult shot, in the parameters of the challenge, in that it is what might be expected, yet much better than expected. for that, congrats!', '2012-05-07 09:32:27.000000', NULL, 0),
(6761892, 1011459, 63218, '<td valign="top">I gave it a 6, it''s a good shot of a reclining cat. But you can tell from the cat''s expression that it is looking at you rightside up. A cat has a remarkable ability to stay rightside up no matter what, so for me the only pose that would work in this challenge is the one with the underside of the cat''s chin/neck showing as it turns its head for a look at the world upside down. It may''ve been an upside down shot to you, but you were there. If it doesn''t feel upside down to me, I have a hard time doing the mental exercise to make it be upside down. It is a good shot, though, &amp; deserving of a 6 no matter what challenge it''s entered in. Meow!</td>', 'I gave it a 6, it''s a good shot of a reclining cat. But you can tell from the cat''s expression that it is looking at you rightside up. A cat has a remarkable ability to stay rightside up no matter what, so for me the only pose that would work in this challenge is the one with the underside of the cat''s chin/neck showing as it turns its head for a look at the world upside down. It may''ve been an upside down shot to you, but you were there. If it doesn''t feel upside down to me, I have a hard time doing the mental exercise to make it be upside down. It is a good shot, though, & deserving of a 6 no matter what challenge it''s entered in. Meow!', '2012-05-07 09:33:54.000000', NULL, 0),
(6761895, 1012452, 12611, '<td valign="top">stunning shot, it immediately left me with the thought that the proportions, the feel, the crop, the facial softness were perfect. congrats.</td>', 'stunning shot, it immediately left me with the thought that the proportions, the feel, the crop, the facial softness were perfect. congrats.', '2012-05-07 09:39:14.000000', NULL, 0),
